ll, "type": "article", "cited_by_count": 0, "open_access": {"is_oa": true, "oa_status": "green", "oa_url": "https://philpapers.org/archive/ZENQGF.pdf", "any_repository_has_fulltext": true}, "primary_location": {"id": "pmh:oai:philpapers.org/rec/ZENQGF", "doi": null, "is_oa": true, "landing_page_url": "https://philpapers.org/rec/ZENQGF", "pdf_url": "https://philpapers.org/archive/ZENQGF.pdf", "source": {"id": "https://openalex.org/S4306402130", "display_name": "PhilPapers (PhilPapers Foundation)", "issn_l": null, "issn": null, "is_oa": false, "is_in_doaj": false, "is_core": false, "listed_in": [], "host_organization": null, "host_organization_name": null, "host_organization_lineage": [], "host_organization_lineage_names": [], "type": "repository"}, "license": null, "license_id": null, "version": "submittedVersion", "is_accepted": false, "is_published": false, "raw_source_name": null, "raw_type": "info:eu-repo/semantics/article"}, "abstract": "This paper derives a theory of quantum gravity from a single axiom: *reality consists of distinctly differentiated structure*. No further assumption is made — not spacetime, not a manifold, not dimension, not a gauge group, not even the framework of quantum mechanics itself. The axiom generates a discrete \"determination-dependency graph,\" a partial order of events becoming actual. On this graph alone, without any continuum, the paper derives the structural core of quantum mechanics (Hilbert space, the complex structure, unitarity, the Born rule, no-cloning) and the structural core of gravity (causal order, relativistic kinematics, gravity identified with geometry via a Benincasa–Dowker-type action, and a time-dependent Schrödinger form of geometric evolution that dissolves the \"frozen time\" problem of canonical quantum gravity). Quantum mechanics and gravity are thus derived as two facets of one structural dynamics rather than reconciled on a manifold. The paper is explicit about what remains borrowed: continuum physics (the Einstein equations, Newton's inverse-square law, exact spacetime dimension) requires an additional, flagged assumption — that structure coarse-grains into a manifold — which the paper shows is *not* borne out by its own formal measure at accessible scales, leaving manifold emergence an open, honestly labelled frontier rather than a hidden premise. A running \"borrowing ledger\" tracks, claim by claim, what is natively derived, what is borrowed from established physics, and what remains open."}]", "excerpt_truncated": true, "source_sha256": "c2b051c4354783a63b49ada0acd4f5291b88dbbc7dc8830aea28fea92e7973ed", "verification_required": true, "topic_domain": "causal_memory", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["openalex:W7169688728", "arxiv:2607.14421"], "source_candidates": ["https://arxiv.org/pdf/2607.14421", "https://arxiv.org/abs/2607.14421"], "source_candidate_identities": {}}
